#include <iostream>
#include <map>
#include <string>
using namespace std;

int main() {
    string a = "";
    string b = "";
    string c = "";
    cin >> a >> b >> c;

    map<string, int> tally;
    tally[a] += 1;
    tally[b] += 1;
    tally[c] += 1;

    for (auto p : tally) {
        cout << p.first << " " << p.second << endl;
    }
    cout << tally.size() << endl;
    return 0;
}
